/**
 * Database schema (Drizzle, SQLite). Conventions:
 * - Primary keys: text UUIDv7 (`id`), generated by the app (or = client opId for commands).
 * - Timestamps: integer epoch milliseconds UTC, suffix `At`.
 * - Local calendar values (dates in the class timezone): text 'YYYY-MM-DD'.
 * - Translatable, teacher-editable labels: JSON `{ en?: string, tr?: string }` (type LocalizedText).
 * - Never hard-delete history: use `archivedAt` / `voidedAt` / `deactivatedAt`.
 * Each stage appends its tables to the relevant section; generate migrations with `npm run db:generate`.
 */
import { sql } from 'drizzle-orm';
import { integer, primaryKey, real, sqliteTable, text, uniqueIndex, index } from 'drizzle-orm/sqlite-core';
import { DEFAULT_SOUND_VOLUME, DEFAULT_WEATHER, TIME_UP_SOUNDS } from '../../shared/classDisplay.ts';
import { FILE_KINDS } from '../../shared/contracts/files.ts';
import { IMPORT_SOURCE_TYPES, type ImportFlag } from '../../shared/contracts/import.ts';
import { STARTER_KINDS } from '../../shared/text/starters.ts';
import { NOTIFICATION_CATEGORIES, NOTIFICATION_ENTITIES } from '../../shared/notifications.ts';

export type LocalizedText = { en?: string; tr?: string };

// ---------------------------------------------------------------- school & settings
export const schoolSettings = sqliteTable('school_settings', {
  id: integer('id').primaryKey(), // always 1
  schoolName: text('school_name').notNull().default('Class Compass School'),
  timezone: text('timezone').notNull().default('Europe/Istanbul'),
  weekStartsOn: integer('week_starts_on').notNull().default(1), // 1 = Monday
  defaultLocale: text('default_locale', { enum: ['en', 'tr'] }).notNull().default('en'),
  /** Classroom weather (S13b, D-106): Open-Meteo for these coordinates; only the coordinates are sent. */
  weatherEnabled: integer('weather_enabled', { mode: 'boolean' }).notNull().default(true),
  weatherLabel: text('weather_label').notNull().default(DEFAULT_WEATHER.label),
  weatherLatitude: real('weather_latitude').notNull().default(DEFAULT_WEATHER.latitude),
  weatherLongitude: real('weather_longitude').notNull().default(DEFAULT_WEATHER.longitude),
  /** Student text checks (S13c, D-123): the minimum length of a goal (words OR letters). */
  textMinGoalWords: integer('text_min_goal_words').notNull().default(3),
  textMinGoalLetters: integer('text_min_goal_letters').notNull().default(12),
  updatedAt: integer('updated_at').notNull(),
});

export const schoolYears = sqliteTable('school_years', {
  id: text('id').primaryKey(),
  name: text('name').notNull(), // e.g. '2026–2027'
  startsOn: text('starts_on').notNull(), // YYYY-MM-DD
  endsOn: text('ends_on').notNull(),
  /** Archived years are read-only (DAT-1): see assertYearWritable. */
  archivedAt: integer('archived_at'),
  createdAt: integer('created_at').notNull(),
  updatedAt: integer('updated_at').notNull(),
});

export const terms = sqliteTable(
  'terms',
  {
    id: text('id').primaryKey(),
    schoolYearId: text('school_year_id').notNull().references(() => schoolYears.id),
    name: text('name', { mode: 'json' }).$type<LocalizedText>().notNull(),
    startsOn: text('starts_on').notNull(),
    endsOn: text('ends_on').notNull(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('terms_year_idx').on(t.schoolYearId)],
);

export const subjects = sqliteTable('subjects', {
  id: text('id').primaryKey(),
  name: text('name', { mode: 'json' }).$type<LocalizedText>().notNull(),
  archivedAt: integer('archived_at'),
  createdAt: integer('created_at').notNull(),
  updatedAt: integer('updated_at').notNull(),
});

/**
 * Theme keys (D-070, D-158): a built-in key or the slug of an imported theme package, stored as plain
 * text, so adding a theme needs no migration. Writes go through `assertThemeUsable` (themes module);
 * reads go through `effectiveTheme`, which falls back to the default theme for a package that is not
 * enabled.
 */

export const classes = sqliteTable(
  'classes',
  {
    id: text('id').primaryKey(),
    schoolYearId: text('school_year_id').notNull().references(() => schoolYears.id),
    name: text('name').notNull(), // e.g. '3-A'
    grade: integer('grade'),
    theme: text('theme').notNull().default('classroom'),
    /** Null = use the school timezone. */
    timezone: text('timezone'),
    soundsEnabled: integer('sounds_enabled', { mode: 'boolean' }).notNull().default(true),
    animationsEnabled: integer('animations_enabled', { mode: 'boolean' }).notNull().default(true),
    /**
     * Class language mode (S13a, D-099): the language of everything class-facing (classroom display,
     * the class's student pages, seeded defaults, label editors). English only by default; the second
     * language ('tr' when main is 'en' and vice versa) only when enabled. Label data in a language that
     * is off is kept, never deleted.
     */
    mainLanguage: text('main_language', { enum: ['en', 'tr'] }).notNull().default('en'),
    secondLanguageEnabled: integer('second_language_enabled', { mode: 'boolean' }).notNull().default(false),
    /** S13b (D-105, D-107): classroom sound volume 0–100, quote of the day on/off, time's-up announcement. */
    soundVolume: integer('sound_volume').notNull().default(DEFAULT_SOUND_VOLUME),
    quoteEnabled: integer('quote_enabled', { mode: 'boolean' }).notNull().default(true),
    timeUpSound: text('time_up_sound', { enum: TIME_UP_SOUNDS }).notNull().default('voice'),
    /**
     * Student-page language override (S13b2, D-117): null = the student pages follow the class mode
     * above; otherwise they use their own main language / second-language switch.
     */
    studentPageMainLanguage: text('student_page_main_language', { enum: ['en', 'tr'] }),
    studentPageSecondLanguageEnabled: integer('student_page_second_language_enabled', { mode: 'boolean' }),
    /** Avatars (S13c, D-124): teachers can stop students changing their avatar; before a student chooses, a generated avatar or the initials. */
    avatarsLocked: integer('avatars_locked', { mode: 'boolean' }).notNull().default(false),
    avatarFallback: text('avatar_fallback', { enum: ['generated', 'initials'] }).notNull().default('generated'),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('classes_year_idx').on(t.schoolYearId)],
);

/** Teacher x class x subject (ARCHITECTURE section 3). Context-owned data hangs off this row. */
export const teachingContexts = sqliteTable(
  'teaching_contexts',
  {
    id: text('id').primaryKey(),
    teacherId: text('teacher_id').notNull().references(() => users.id),
    classId: text('class_id').notNull().references(() => classes.id),
    subjectId: text('subject_id').notNull().references(() => subjects.id),
    activeFrom: integer('active_from').notNull(),
    endedAt: integer('ended_at'),
    createdAt: integer('created_at').notNull(),
  },
  (t) => [
    uniqueIndex('teaching_contexts_active_uq').on(t.teacherId, t.classId, t.subjectId).where(sql`ended_at IS NULL`),
    index('teaching_contexts_class_idx').on(t.classId),
    index('teaching_contexts_teacher_idx').on(t.teacherId),
  ],
);

/** Admin-controlled global availability per module (ACC-12, CFG-1, D-014). */
export const modulePolicies = sqliteTable('module_policies', {
  module: text('module').primaryKey(),
  availability: text('availability', { enum: ['enabled', 'disabled'] }).notNull(),
  updatedAt: integer('updated_at').notNull(),
  updatedBy: text('updated_by'),
});

/** Teacher's per-context module switch + config (ACC-5). No row = enabled with defaults. */
export const contextModules = sqliteTable(
  'context_modules',
  {
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    module: text('module').notNull(),
    enabled: integer('enabled', { mode: 'boolean' }).notNull(),
    configJson: text('config_json'),
    updatedAt: integer('updated_at').notNull(),
    updatedBy: text('updated_by'),
  },
  (t) => [primaryKey({ columns: [t.contextId, t.module] })],
);

// ---------------------------------------------------------------- accounts
export const users = sqliteTable(
  'users',
  {
    id: text('id').primaryKey(),
    login: text('login').notNull(), // stored lower-cased (tr-insensitive fold applied by service)
    email: text('email'),
    displayName: text('display_name').notNull(),
    role: text('role', { enum: ['admin', 'teacher'] }).notNull(),
    passwordHash: text('password_hash').notNull(),
    pinHash: text('pin_hash'),
    locale: text('locale', { enum: ['en', 'tr'] }).notNull().default('en'),
    textScale: integer('text_scale').notNull().default(100),
    mustChangePassword: integer('must_change_password', { mode: 'boolean' }).notNull().default(false),
    /**
     * S13b (D-108): how the account signs in. 'email_link' accounts have no password (`passwordHash`
     * is '' and never verifies); administrators always use 'password'. `emailVerifiedAt` is set when
     * an invite or a sign-in link sent to the address was used.
     */
    signInMethod: text('sign_in_method', { enum: ['password', 'email_link'] }).notNull().default('password'),
    emailVerifiedAt: integer('email_verified_at'),
    /** The teacher's recorded time's-up clip (files.kind 'teacher_sound', D-107); null = none. */
    timeUpClipFileId: text('time_up_clip_file_id'),
    disabledAt: integer('disabled_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [uniqueIndex('users_login_uq').on(t.login)],
);

export const SESSION_KINDS = ['user', 'student', 'scorer', 'display'] as const;

export const sessions = sqliteTable(
  'sessions',
  {
    id: text('id').primaryKey(),
    tokenHash: text('token_hash').notNull(),
    /** S12 (D-128): 'scorer' and 'display' sessions come only from Super Speakers links. */
    kind: text('kind', { enum: SESSION_KINDS }).notNull(),
    userId: text('user_id').references(() => users.id),
    studentLinkId: text('student_link_id'),
    /** Super Speakers scorer link (S12): every request re-checks it, so a revoke ends the session at once. */
    scorerLinkId: text('scorer_link_id'),
    /** Super Speakers board (display) link (S12). */
    displayLinkId: text('display_link_id'),
    classroomMode: integer('classroom_mode', { mode: 'boolean' }).notNull().default(false),
    pinUnlockedUntil: integer('pin_unlocked_until'),
    pinFailures: integer('pin_failures').notNull().default(0),
    pinLockedUntil: integer('pin_locked_until'),
    /** How the session was signed in (S13b, D-108): a fresh email-link/invite session counts as re-authentication for 15 minutes. */
    authMethod: text('auth_method', { enum: ['password', 'email_link', 'invite', 'student_link', 'scorer_link', 'scorer_pairing', 'display_link'] }),
    createdAt: integer('created_at').notNull(),
    lastSeenAt: integer('last_seen_at').notNull(),
    expiresAt: integer('expires_at').notNull(),
    revokedAt: integer('revoked_at'),
  },
  (t) => [
    uniqueIndex('sessions_token_uq').on(t.tokenHash),
    index('sessions_user_idx').on(t.userId),
    index('sessions_scorer_link_idx').on(t.scorerLinkId),
    index('sessions_display_link_idx').on(t.displayLinkId),
  ],
);

/** Login throttling per account and per IP. */
export const authAttempts = sqliteTable(
  'auth_attempts',
  {
    key: text('key').primaryKey(), // e.g. 'login:user:<id>' | 'login:ip:<ip>'
    failures: integer('failures').notNull().default(0),
    lockedUntil: integer('locked_until'),
    updatedAt: integer('updated_at').notNull(),
  },
);

export const oneTimeTokens = sqliteTable('one_time_tokens', {
  id: text('id').primaryKey(),
  /** 'invite' (7 days, S13b), 'email_signin' (15 minutes, link + 6-digit code, S13b), 'password_reset'. */
  kind: text('kind', { enum: ['password_reset', 'invite', 'email_signin'] }).notNull(),
  userId: text('user_id').notNull().references(() => users.id),
  tokenHash: text('token_hash').notNull(),
  expiresAt: integer('expires_at').notNull(),
  usedAt: integer('used_at'),
  /** Invites: revoked by an administrator (or replaced by a new one). */
  revokedAt: integer('revoked_at'),
  /** Email sign-in: HMAC of the 6-digit code, the requesting device's binding and the wrong tries. */
  codeHash: text('code_hash'),
  bindingHash: text('binding_hash'),
  codeAttempts: integer('code_attempts').notNull().default(0),
  /** Invites: the link was emailed to the account's address, so using it proves the address. */
  sentByEmail: integer('sent_by_email', { mode: 'boolean' }).notNull().default(false),
  createdBy: text('created_by'),
  createdAt: integer('created_at').notNull(),
}, (t) => [uniqueIndex('one_time_tokens_hash_uq').on(t.tokenHash), index('one_time_tokens_user_idx').on(t.userId)]);

// ---------------------------------------------------------------- idempotency & audit
/** Every client command (opId) is recorded with its result in the same transaction as its effect. */
export const commandLog = sqliteTable('command_log', {
  opId: text('op_id').primaryKey(),
  actorKey: text('actor_key').notNull(), // 'user:<id>' | 'student:<id>'
  type: text('type').notNull(),
  requestHash: text('request_hash').notNull(),
  resultJson: text('result_json').notNull(),
  createdAt: integer('created_at').notNull(),
});

/** Insert-only audit trail for important edits (DAT-5, ACC-9). */
export const auditEvents = sqliteTable(
  'audit_events',
  {
    id: text('id').primaryKey(),
    at: integer('at').notNull(),
    /** 'scorer' = a Super Speakers scorer link (actorId = the link id), 'display' = a board link (S12). */
    actorType: text('actor_type', { enum: ['user', 'student', 'system', 'scorer', 'display'] }).notNull(),
    actorId: text('actor_id'),
    opId: text('op_id'),
    action: text('action').notNull(),
    entity: text('entity').notNull(),
    entityId: text('entity_id'),
    beforeJson: text('before_json'),
    afterJson: text('after_json'),
  },
  (t) => [index('audit_entity_idx').on(t.entity, t.entityId), index('audit_at_idx').on(t.at)],
);

// ---------------------------------------------------------------- students
/** One identity per student across classes and years (ACC-7). */
export const students = sqliteTable(
  'students',
  {
    id: text('id').primaryKey(),
    /** e-Okul number; optional but unique when present (IMP-4). */
    studentNumber: text('student_number'),
    fullName: text('full_name').notNull(), // NFC, whitespace-collapsed (normaliseName)
    givenNames: text('given_names'),
    familyName: text('family_name'),
    nameFold: text('name_fold').notNull(), // foldForSearch(fullName): duplicate flagging/search only
    avatarHue: integer('avatar_hue').notNull(), // avatarHue(id): stable across renames
    photoFileId: text('photo_file_id'),
    photoConsent: integer('photo_consent', { mode: 'boolean' }).notNull().default(false),
    /** The student's own avatar (S13c, D-124): a catalogue spec validated on every write; null = not chosen yet. */
    avatarJson: text('avatar_json', { mode: 'json' }).$type<Record<string, unknown>>(),
    avatarUpdatedAt: integer('avatar_updated_at'),
    deactivatedAt: integer('deactivated_at'),
    createdByImportBatchId: text('created_by_import_batch_id'),
    createdAt: integer('created_at').notNull(),
    createdBy: text('created_by'),
    updatedAt: integer('updated_at').notNull(),
    updatedBy: text('updated_by'),
  },
  (t) => [uniqueIndex('students_number_uq').on(t.studentNumber), index('students_fold_idx').on(t.nameFold)],
);

/**
 * Class membership history (DAT-2). `fromDate` inclusive, `toDate` exclusive (the day the student
 * left); `toDate` null = current. At most one open enrolment per student per school year.
 */
export const enrolments = sqliteTable(
  'enrolments',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    classId: text('class_id').notNull().references(() => classes.id),
    schoolYearId: text('school_year_id').notNull().references(() => schoolYears.id),
    fromDate: text('from_date').notNull(),
    toDate: text('to_date'),
    reason: text('reason', { enum: ['added', 'import', 'move', 'promotion'] }).notNull(),
    importBatchId: text('import_batch_id'),
    createdAt: integer('created_at').notNull(),
    createdBy: text('created_by'),
  },
  (t) => [
    uniqueIndex('enrolments_open_uq').on(t.studentId, t.schoolYearId).where(sql`to_date IS NULL`),
    index('enrolments_class_idx').on(t.classId),
    index('enrolments_student_idx').on(t.studentId),
  ],
);

/** Subject-specific levels for grouping (GRP-3). Never returned by classroom endpoints (GRP-7). */
export const studentSubjectLevels = sqliteTable(
  'student_subject_levels',
  {
    studentId: text('student_id').notNull().references(() => students.id),
    subjectId: text('subject_id').notNull().references(() => subjects.id),
    level: text('level').notNull(),
    updatedBy: text('updated_by'),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [primaryKey({ columns: [t.studentId, t.subjectId] })],
);

// ---------------------------------------------------------------- lessons & routines (S5)
export type StageJson = { id: string; name: LocalizedText };
export type TimerJson = { durationMs: number; startedAt: number | null; remainingMs: number; running: boolean };
export type ReflectionJson = { rating: number | null; note: string | null };

/**
 * Routine templates (RTN-2). Owned by one teacher; `contextId` null = usable in all of the
 * teacher's classes. The built-in default routine (RTN-1) is code, not a row (DEFAULT_ROUTINE_ID).
 */
export const routineTemplates = sqliteTable(
  'routine_templates',
  {
    id: text('id').primaryKey(),
    teacherId: text('teacher_id').notNull().references(() => users.id),
    contextId: text('context_id').references(() => teachingContexts.id),
    name: text('name', { mode: 'json' }).$type<LocalizedText>().notNull(),
    stagesJson: text('stages_json', { mode: 'json' }).$type<StageJson[]>().notNull(),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('routine_templates_teacher_idx').on(t.teacherId)],
);

/** Per-context lesson settings: the routine a new lesson starts with by default (RTN-2, CFG-3). */
export const contextLessonSettings = sqliteTable('context_lesson_settings', {
  contextId: text('context_id').primaryKey().references(() => teachingContexts.id),
  /** A routine_templates id or DEFAULT_ROUTINE_ID. */
  defaultTemplateId: text('default_template_id').notNull(),
  /**
   * Weekly topic plan (S13a, D-101): ISO weekday (1 = Monday … 7) → skill category ids used as the
   * default lesson topics on that day. Optional; `{}` = no plan.
   */
  topicPlanJson: text('topic_plan_json', { mode: 'json' }).$type<Record<string, string[]>>().notNull().default(sql`'{}'`),
  updatedAt: integer('updated_at').notNull(),
  updatedBy: text('updated_by'),
});

export type LessonTopicJson = { id: string; name: LocalizedText; icon: string | null };
export type LessonDisplayJson = { assistantVisible?: boolean };

/**
 * Lessons (LES-1..4). At most one ACTIVE lesson per teaching context (DB-enforced). The routine is
 * snapshotted at start, so template edits never change a running lesson. `version` increases on
 * every lesson-state change (ETag for polling). Name snapshots keep history readable (DAT-6).
 */
export const lessons = sqliteTable(
  'lessons',
  {
    id: text('id').primaryKey(), // = opId of the 'lesson.start' command
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    teacherId: text('teacher_id').notNull().references(() => users.id),
    classId: text('class_id').notNull().references(() => classes.id),
    status: text('status', { enum: ['active', 'ended', 'abandoned'] }).notNull(),
    startedAt: integer('started_at').notNull(),
    endedAt: integer('ended_at'),
    localDate: text('local_date').notNull(), // class timezone, at start
    routineTemplateId: text('routine_template_id'),
    routineNameJson: text('routine_name_json', { mode: 'json' }).$type<LocalizedText>().notNull(),
    routineSnapshotJson: text('routine_snapshot_json', { mode: 'json' }).$type<StageJson[]>().notNull(),
    stageIndex: integer('stage_index').notNull().default(0),
    timerJson: text('timer_json', { mode: 'json' }).$type<TimerJson>().notNull(),
    reflectionJson: text('reflection_json', { mode: 'json' }).$type<ReflectionJson>(),
    /** Today's topic(s) / skill focus (S13a, D-101): category ids with name + icon snapshots (DAT-6). */
    topicsJson: text('topics_json', { mode: 'json' }).$type<LessonTopicJson[]>().notNull().default(sql`'[]'`),
    /** Per-lesson display choices (S13a): null = the class default (e.g. the assistant panel shown). */
    displayJson: text('display_json', { mode: 'json' }).$type<LessonDisplayJson>().notNull().default(sql`'{}'`),
    version: integer('version').notNull().default(1),
    classNameSnapshot: text('class_name_snapshot').notNull(),
    subjectNameSnapshot: text('subject_name_snapshot', { mode: 'json' }).$type<LocalizedText>().notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [
    uniqueIndex('lessons_one_active_uq').on(t.contextId).where(sql`status = 'active'`),
    index('lessons_context_idx').on(t.contextId, t.startedAt),
    index('lessons_class_date_idx').on(t.classId, t.localDate),
  ],
);

// ---------------------------------------------------------------- attendance (S5)
export const ATTENDANCE_STATUS_VALUES = ['present', 'absent', 'late', 'excused'] as const;

/**
 * Daily attendance (ACC-8, ATT-2): one row per student and local date, SHARED by every teacher of
 * the class. Every change is audited with its actor (ACC-9). Independent of homework (ATT-1).
 */
export const attendanceDaily = sqliteTable(
  'attendance_daily',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    classId: text('class_id').notNull().references(() => classes.id),
    localDate: text('local_date').notNull(),
    status: text('status', { enum: ATTENDANCE_STATUS_VALUES }).notNull(),
    note: text('note'),
    recordedBy: text('recorded_by').notNull().references(() => users.id),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [uniqueIndex('attendance_daily_student_date_uq').on(t.studentId, t.localDate), index('attendance_daily_class_date_idx').on(t.classId, t.localDate)],
);

/** Lesson-specific exceptions (ATT-2): override the daily status for one lesson only. */
export const attendanceLessonExceptions = sqliteTable(
  'attendance_lesson_exceptions',
  {
    lessonId: text('lesson_id').notNull().references(() => lessons.id),
    studentId: text('student_id').notNull().references(() => students.id),
    status: text('status', { enum: ATTENDANCE_STATUS_VALUES }).notNull(),
    note: text('note'),
    recordedBy: text('recorded_by').notNull().references(() => users.id),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [primaryKey({ columns: [t.lessonId, t.studentId] })],
);

// ---------------------------------------------------------------- counters (S6)
export type CounterLabelsJson = { main: LocalizedText; supporting: LocalizedText; individual: LocalizedText };
export type ThresholdResponseJson = {
  id: string;
  label: LocalizedText;
  message: LocalizedText;
  mascot: boolean;
  kind: 'message' | 'no_breaktime' | 'class_reset' | 'practice_challenge' | 'custom';
};
export type CounterLabelSnapshotJson = { main: LocalizedText; individual: LocalizedText };

/**
 * Counters (CNT-1..12) owned by a teaching context (ACC-10). `kind` english_reminders = the English
 * preset (CNT-1), custom = teacher-made (CNT-12). `barSegments` is the lesson threshold (class bar
 * limit). `studentThresholdsJson` = ascending visual levels of individual counts (CNT-6);
 * `responsesJson` = threshold responses, `activeResponseId` the selected one (CNT-9). Archived
 * counters disappear from the classroom; their events stay (CFG-2).
 */
export const counters = sqliteTable(
  'counters',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    kind: text('kind', { enum: ['english_reminders', 'custom'] }).notNull(),
    labelsJson: text('labels_json', { mode: 'json' }).$type<CounterLabelsJson>().notNull(),
    scope: text('scope', { enum: ['lesson', 'student', 'both'] }).notNull(),
    barSegments: integer('bar_segments').notNull().default(10),
    studentResetPeriod: text('student_reset_period', { enum: ['week', 'term', 'never'] }).notNull().default('week'),
    studentThresholdsJson: text('student_thresholds_json', { mode: 'json' }).$type<number[]>().notNull(),
    responsesJson: text('responses_json', { mode: 'json' }).$type<ThresholdResponseJson[]>().notNull(),
    activeResponseId: text('active_response_id'),
    colour: text('colour').notNull().default('accent'),
    sortOrder: integer('sort_order').notNull().default(0),
    archivedAt: integer('archived_at'),
    createdBy: text('created_by').notNull().references(() => users.id),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('counters_context_idx').on(t.contextId)],
);

/**
 * One tap = one event (CNT-3). id = the opId of the 'counter.tap' command, so a retried or replayed
 * tap can never count twice (CNT-5). `studentId` null = class-only tap. `seq` orders events within
 * a lesson (reset markers refer to it). `localDate` / `weekStart` are computed at write time in the
 * class timezone (D-003). Undo voids the event (actor + time + opId) and never deletes it (CNT-4).
 * `labelSnapshotJson` keeps the labels used at the time (DAT-6).
 */
export const counterEvents = sqliteTable(
  'counter_events',
  {
    id: text('id').primaryKey(),
    counterId: text('counter_id').notNull().references(() => counters.id),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    lessonId: text('lesson_id').notNull().references(() => lessons.id),
    studentId: text('student_id').references(() => students.id),
    seq: integer('seq').notNull(),
    occurredAt: integer('occurred_at').notNull(),
    localDate: text('local_date').notNull(),
    weekStart: text('week_start').notNull(),
    recordedBy: text('recorded_by').notNull().references(() => users.id),
    voidedAt: integer('voided_at'),
    voidedBy: text('voided_by').references(() => users.id),
    voidOpId: text('void_op_id'),
    labelSnapshotJson: text('label_snapshot_json', { mode: 'json' }).$type<CounterLabelSnapshotJson>().notNull(),
  },
  (t) => [
    uniqueIndex('counter_events_lesson_seq_uq').on(t.counterId, t.lessonId, t.seq),
    index('counter_events_student_week_idx').on(t.counterId, t.studentId, t.weekStart),
    index('counter_events_lesson_idx').on(t.lessonId),
  ],
);

/**
 * Threshold crossings of a lesson's class bar (D-004). A crossing opens when the bar reaches the
 * limit (the response fires once for it) and is cleared when the bar drops below the limit (void) or
 * the class bar is reset. `eventId` is the event that completed the bar: kept for accountability,
 * never sent to the classroom (CNT-9).
 */
export const thresholdCrossings = sqliteTable(
  'threshold_crossings',
  {
    id: text('id').primaryKey(),
    counterId: text('counter_id').notNull().references(() => counters.id),
    lessonId: text('lesson_id').notNull().references(() => lessons.id),
    crossingSeq: integer('crossing_seq').notNull(),
    crossedAt: integer('crossed_at').notNull(),
    clearedAt: integer('cleared_at'),
    clearedReason: text('cleared_reason', { enum: ['void', 'reset', 'limit'] }),
    eventId: text('event_id').notNull(),
    responseId: text('response_id'),
  },
  (t) => [uniqueIndex('threshold_crossings_seq_uq').on(t.counterId, t.lessonId, t.crossingSeq)],
);

/**
 * Class bar reset markers (D-058): the bar shows live events with seq > afterSeq of the latest
 * marker; events are never deleted, so the lesson total (CNT-8) and weekly counts are unchanged.
 */
export const counterLessonResets = sqliteTable(
  'counter_lesson_resets',
  {
    id: text('id').primaryKey(), // = opId
    counterId: text('counter_id').notNull().references(() => counters.id),
    lessonId: text('lesson_id').notNull().references(() => lessons.id),
    afterSeq: integer('after_seq').notNull(),
    resetAt: integer('reset_at').notNull(),
    resetBy: text('reset_by').notNull().references(() => users.id),
  },
  (t) => [index('counter_lesson_resets_idx').on(t.counterId, t.lessonId)],
);

// ---------------------------------------------------------------- secret students (S7)
export const SECRET_SELECTION_STATUSES = ['sealed', 'withdrawn_absent', 'withdrawn_redraw', 'revealed', 'unrevealed_abandoned'] as const;
export const SECRET_OUTCOMES = ['goal_met', 'still_practising', 'not_assessed'] as const;

/**
 * One Secret Student draw per lesson (SEC-1..7). id = the opId of the 'secret.draw' (or
 * 'secret.redraw') command. At most one LIVE round per lesson (DB-enforced); a redraw marks the old
 * round 'withdrawn'. `selectedCount` is the number chosen at draw time and never changes afterwards,
 * so a silent replacement or withdrawal can never show up in the classroom state (SEC-3, D-064).
 * `schoolYearId` scopes the fair rotation (D-062).
 */
export const secretRounds = sqliteTable(
  'secret_rounds',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    lessonId: text('lesson_id').notNull().references(() => lessons.id),
    schoolYearId: text('school_year_id').notNull().references(() => schoolYears.id),
    localDate: text('local_date').notNull(),
    status: text('status', { enum: ['live', 'withdrawn'] }).notNull(),
    requestedCount: integer('requested_count').notNull(),
    selectedCount: integer('selected_count').notNull(),
    shortfallReason: text('shortfall_reason', { enum: ['NOT_ENOUGH_ELIGIBLE', 'NO_ELIGIBLE'] }),
    drawnAt: integer('drawn_at').notNull(),
    drawnBy: text('drawn_by').notNull().references(() => users.id),
    revealedAt: integer('revealed_at'),
    withdrawnAt: integer('withdrawn_at'),
    opId: text('op_id').notNull(),
  },
  (t) => [
    uniqueIndex('secret_rounds_live_uq').on(t.lessonId).where(sql`status = 'live'`),
    index('secret_rounds_context_idx').on(t.contextId, t.schoolYearId),
  ],
);

/**
 * The students of a round. SECRET: `studentId` of a round that is not revealed may only be read by
 * src/server/modules/secret (enforced by tests/server/secret-boundary.test.ts). `replacedSelectionId`
 * on a replacement points at the withdrawn selection it replaced (D-007).
 */
export const secretSelections = sqliteTable(
  'secret_selections',
  {
    id: text('id').primaryKey(),
    roundId: text('round_id').notNull().references(() => secretRounds.id),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    studentId: text('student_id').notNull().references(() => students.id),
    status: text('status', { enum: SECRET_SELECTION_STATUSES }).notNull(),
    replacedSelectionId: text('replaced_selection_id'),
    outcome: text('outcome', { enum: SECRET_OUTCOMES }),
    note: text('note'),
    celebration: integer('celebration', { mode: 'boolean' }).notNull().default(false),
    selectedAt: integer('selected_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    outcomeBy: text('outcome_by').references(() => users.id),
  },
  (t) => [
    uniqueIndex('secret_selections_round_student_uq').on(t.roundId, t.studentId),
    index('secret_selections_context_student_idx').on(t.contextId, t.studentId),
  ],
);

// ---------------------------------------------------------------- daily assistant (S7)
export const ASSISTANT_STATUSES = ['planned', 'confirmed', 'replaced_absent', 'swapped', 'override'] as const;

/** State before an absence replacement, so a same-day attendance correction can restore it (D-068). */
export interface AssistantAbsenceUndo {
  absentId: string;
  replacement: string | null;
  prev: { actualStudentId: string | null; status: (typeof ASSISTANT_STATUSES)[number]; reason: string | null };
  partner: { id: string; actualStudentId: string | null; status: (typeof ASSISTANT_STATUSES)[number]; reason: string | null } | null;
}

/** A materialised weekly plan (AST-2): generated once, never regenerated silently, announceable. */
export const assistantPlans = sqliteTable(
  'assistant_plans',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    weekStart: text('week_start').notNull(),
    generatedAt: integer('generated_at').notNull(),
    generatedBy: text('generated_by').references(() => users.id),
    announcedAt: integer('announced_at'),
    announcedBy: text('announced_by').references(() => users.id),
  },
  (t) => [uniqueIndex('assistant_plans_context_week_uq').on(t.contextId, t.weekStart)],
);

/**
 * One assistant per context and local day (AST-1, DB-enforced). `plannedStudentId` is what the plan
 * said; `actualStudentId` is set when someone else did/does the job (absence, swap, override), so
 * planned vs actual is kept (AST-5). The effective assistant is actual ?? planned.
 */
export const assistantAssignments = sqliteTable(
  'assistant_assignments',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    planId: text('plan_id').references(() => assistantPlans.id),
    schoolYearId: text('school_year_id').notNull().references(() => schoolYears.id),
    localDate: text('local_date').notNull(),
    plannedStudentId: text('planned_student_id').references(() => students.id),
    actualStudentId: text('actual_student_id').references(() => students.id),
    status: text('status', { enum: ASSISTANT_STATUSES }).notNull(),
    reason: text('reason'),
    /**
     * Every student who was this day's assistant and missed the turn because they were away (AST-4/5).
     * Kept when the day is later swapped or overridden, so a missed turn is never lost (review fix).
     */
    absentStudentIds: text('absent_student_ids', { mode: 'json' }).$type<string[]>().notNull().default(sql`'[]'`),
    /** How to undo the latest absence replacement if the attendance is corrected the same day (D-068). */
    absenceUndo: text('absence_undo', { mode: 'json' }).$type<AssistantAbsenceUndo>(),
    thankedAt: integer('thanked_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    updatedBy: text('updated_by').references(() => users.id),
  },
  (t) => [uniqueIndex('assistant_assignments_context_date_uq').on(t.contextId, t.localDate), index('assistant_assignments_year_idx').on(t.contextId, t.schoolYearId)],
);

/** Editable responsibilities of the assistant per context (AST-6); archived instead of deleted. */
export const assistantResponsibilities = sqliteTable(
  'assistant_responsibilities',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    labelJson: text('label_json', { mode: 'json' }).$type<LocalizedText>().notNull(),
    sortOrder: integer('sort_order').notNull(),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('assistant_responsibilities_context_idx').on(t.contextId)],
);

/**
 * Assistant duty ticks (S13a, D-100): one row per context, day, student and responsibility, ticked on
 * the classroom screen through outbox commands (id = opId of the tick). Unticking sets `uncheckedAt`
 * (history kept); ticking again revives the row.
 */
export const assistantDutyChecks = sqliteTable(
  'assistant_duty_checks',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    localDate: text('local_date').notNull(),
    studentId: text('student_id').notNull().references(() => students.id),
    responsibilityId: text('responsibility_id').notNull().references(() => assistantResponsibilities.id),
    checkedAt: integer('checked_at').notNull(),
    checkedBy: text('checked_by').notNull().references(() => users.id),
    uncheckedAt: integer('unchecked_at'),
  },
  (t) => [uniqueIndex('assistant_duty_checks_uq').on(t.contextId, t.localDate, t.studentId, t.responsibilityId), index('assistant_duty_checks_date_idx').on(t.contextId, t.localDate)],
);

// ---------------------------------------------------------------- grouping (S8)
export type GroupJson = { id: string; name: LocalizedText; icon: string; memberIds: string[]; roles: Array<{ studentId: string; label: LocalizedText }> };
export type SizingJson = { groupCount: number } | { targetSize: number };
export type UnsatisfiedJson = { ruleId: string; a: string; b: string; kind: 'together' | 'apart'; reason: string };

/**
 * Saved group arrangements per teaching context (GRP-1..3, GRP-6). `mode` level / mixed (generated by
 * the solver from `seed`) or custom (hand-made). `version` increases on every change; a lesson keeps
 * the version it used. `defaultKey` marks the five defaults (GRP-1), created once per context while
 * it has no arrangement row at all (an archived default is never recreated). Archived, never deleted.
 */
export const groupTemplates = sqliteTable(
  'group_templates',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    name: text('name', { mode: 'json' }).$type<LocalizedText>().notNull(),
    mode: text('mode', { enum: ['level', 'mixed', 'custom'] }).notNull(),
    sizingJson: text('sizing_json', { mode: 'json' }).$type<SizingJson>().notNull(),
    seed: text('seed').notNull(),
    version: integer('version').notNull().default(1),
    groupsJson: text('groups_json', { mode: 'json' }).$type<GroupJson[]>().notNull(),
    unsatisfiedJson: text('unsatisfied_json', { mode: 'json' }).$type<UnsatisfiedJson[]>().notNull(),
    defaultKey: text('default_key'),
    /** Option icon key (S13a, GRP-1 change: lion, eagle, dolphin, tiger…); null = a generic group icon. */
    icon: text('icon'),
    sortOrder: integer('sort_order').notNull().default(0),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    createdBy: text('created_by').references(() => users.id),
    updatedAt: integer('updated_at').notNull(),
    updatedBy: text('updated_by').references(() => users.id),
  },
  (t) => [index('group_templates_context_idx').on(t.contextId)],
);

/**
 * Pair rules (GRP-4): two students who should work together (soft) or apart (hard where possible).
 * `studentA` < `studentB` (normalised). PRIVATE: teacher area only, never on the classroom screen
 * (GRP-7). Removing a rule archives it.
 */
export const pairConstraints = sqliteTable(
  'pair_constraints',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    studentA: text('student_a').notNull().references(() => students.id),
    studentB: text('student_b').notNull().references(() => students.id),
    kind: text('kind', { enum: ['together', 'apart'] }).notNull(),
    note: text('note'),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    createdBy: text('created_by').references(() => users.id),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [uniqueIndex('pair_constraints_live_uq').on(t.contextId, t.studentA, t.studentB).where(sql`archived_at IS NULL`)],
);

/**
 * The groups used in a lesson (GRP-5): a copy of the arrangement fitted to the students present,
 * so absences never change the saved arrangement. id = opId of 'grouping.apply'. At most one live
 * grouping per lesson; applying another or clearing marks the previous one `clearedAt`.
 */
export const lessonGroupings = sqliteTable(
  'lesson_groupings',
  {
    id: text('id').primaryKey(),
    lessonId: text('lesson_id').notNull().references(() => lessons.id),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    templateId: text('template_id').notNull().references(() => groupTemplates.id),
    templateVersion: integer('template_version').notNull(),
    effectiveGroupsJson: text('effective_groups_json', { mode: 'json' }).$type<GroupJson[]>().notNull(),
    excludedAbsentIds: text('excluded_absent_ids', { mode: 'json' }).$type<string[]>().notNull(),
    unsatisfiedJson: text('unsatisfied_json', { mode: 'json' }).$type<UnsatisfiedJson[]>().notNull(),
    appliedAt: integer('applied_at').notNull(),
    appliedBy: text('applied_by').notNull().references(() => users.id),
    clearedAt: integer('cleared_at'),
  },
  (t) => [uniqueIndex('lesson_groupings_live_uq').on(t.lessonId).where(sql`cleared_at IS NULL`), index('lesson_groupings_context_idx').on(t.contextId)],
);

// ---------------------------------------------------------------- homework (S8)
export type HomeworkStatusJson = { key: string; label: LocalizedText; kind: string };

/**
 * Homework assignments per teaching context (HW-1..3). The subject comes from the context.
 * `statusSetJson` is the status list snapshot used for this assignment (HW-2). Archived, never deleted.
 */
export const homeworkAssignments = sqliteTable(
  'homework_assignments',
  {
    id: text('id').primaryKey(),
    contextId: text('context_id').notNull().references(() => teachingContexts.id),
    title: text('title').notNull(),
    details: text('details'),
    assignedOn: text('assigned_on').notNull(),
    dueOn: text('due_on').notNull(),
    notes: text('notes'),
    statusSetJson: text('status_set_json', { mode: 'json' }).$type<HomeworkStatusJson[]>().notNull(),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    createdBy: text('created_by').references(() => users.id),
    updatedAt: integer('updated_at').notNull(),
    updatedBy: text('updated_by').references(() => users.id),
  },
  (t) => [index('homework_context_due_idx').on(t.contextId, t.dueOn), index('homework_context_assigned_idx').on(t.contextId, t.assignedOn)],
);

/**
 * One reviewed status per student and assignment (HW-4). NO ROW = NOT CHECKED, which is never
 * "missing". Attendance is not stored here (ATT-1).
 */
export const homeworkMarks = sqliteTable(
  'homework_marks',
  {
    assignmentId: text('assignment_id').notNull().references(() => homeworkAssignments.id),
    studentId: text('student_id').notNull().references(() => students.id),
    status: text('status').notNull(),
    note: text('note'),
    updatedBy: text('updated_by').notNull().references(() => users.id),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [primaryKey({ columns: [t.assignmentId, t.studentId] })],
);

/**
 * Every mark change, grouped by batch (one tap, "mark selected", "mark all remaining"), so a batch can
 * be undone (UX-9) and the history is kept. A null status = no mark (not checked).
 */
export const homeworkMarkChanges = sqliteTable(
  'homework_mark_changes',
  {
    id: text('id').primaryKey(),
    batchId: text('batch_id').notNull(),
    assignmentId: text('assignment_id').notNull().references(() => homeworkAssignments.id),
    studentId: text('student_id').notNull().references(() => students.id),
    beforeStatus: text('before_status'),
    beforeNote: text('before_note'),
    afterStatus: text('after_status'),
    afterNote: text('after_note'),
    changedAt: integer('changed_at').notNull(),
    changedBy: text('changed_by').notNull().references(() => users.id),
    undoneAt: integer('undone_at'),
    undoneBy: text('undone_by').references(() => users.id),
  },
  (t) => [index('homework_mark_changes_batch_idx').on(t.batchId), index('homework_mark_changes_assignment_idx').on(t.assignmentId, t.studentId)],
);

// ---------------------------------------------------------------- files (S9)

/**
 * Uploaded files (STU-8, D-014). Bytes live under DATA_DIR/uploads at `storageKey` (random
 * `xx/yy/<uuid>`, no extension, never derived from the client's name); images are re-encoded (EXIF/GPS
 * stripped) and get a thumbnail at `thumbStorageKey`. `sniffedMime` comes from the content, never
 * from the client. `ownerStudentId` scopes access and the per-student quota. Served only through the
 * policy-checked file endpoints. Deleted files keep their row (`deletedAt`); the bytes are removed.
 */
export const files = sqliteTable(
  'files',
  {
    id: text('id').primaryKey(),
    storageKey: text('storage_key').notNull(),
    thumbStorageKey: text('thumb_storage_key'),
    sha256: text('sha256').notNull(),
    size: integer('size').notNull(),
    thumbSize: integer('thumb_size'),
    sniffedMime: text('sniffed_mime').notNull(),
    kind: text('kind', { enum: FILE_KINDS }).notNull(),
    /** Display name for downloads only (sanitised); never used for storage or type decisions. */
    originalName: text('original_name'),
    ownerStudentId: text('owner_student_id').references(() => students.id),
    uploadedByType: text('uploaded_by_type', { enum: ['user', 'student', 'system'] }).notNull(),
    uploadedById: text('uploaded_by_id'),
    createdAt: integer('created_at').notNull(),
    deletedAt: integer('deleted_at'),
  },
  (t) => [uniqueIndex('files_storage_key_uq').on(t.storageKey), index('files_owner_idx').on(t.ownerStudentId), index('files_uploader_idx').on(t.uploadedById)],
);

// ---------------------------------------------------------------- student list importer (S9)
export type ImportParsedJson = { fullName: string; givenNames: string | null; familyName: string | null; studentNumber: string | null; className: string | null };
export type ImportMappingJson = { headerRow: number | null; fullName: number | null; givenNames: number | null; familyName: number | null; studentNumber: number | null; className: number | null };
export type ImportCandidateJson = { id: string; fullName: string; className: string | null; studentNumber: string | null; active: boolean; score: number };
export type ImportCountsJson = Record<string, number>;

/**
 * One import of a student list into a class (IMP-1..5). A draft holds the extracted rows for the
 * editable preview; commit creates/matches students; revert undoes what the batch created when
 * nothing has happened to it since (otherwise it deactivates and reports).
 */
export const importBatches = sqliteTable(
  'import_batches',
  {
    id: text('id').primaryKey(),
    sourceType: text('source_type', { enum: IMPORT_SOURCE_TYPES }).notNull(),
    fileId: text('file_id').references(() => files.id),
    targetClassId: text('target_class_id').notNull().references(() => classes.id),
    schoolYearId: text('school_year_id').notNull().references(() => schoolYears.id),
    createdBy: text('created_by').notNull().references(() => users.id),
    status: text('status', { enum: ['draft', 'committed', 'reverted'] }).notNull(),
    /** Column labels of the extracted table (for the field mapping) and the current mapping. */
    columnsJson: text('columns_json', { mode: 'json' }).$type<string[]>().notNull(),
    mappingJson: text('mapping_json', { mode: 'json' }).$type<ImportMappingJson>().notNull(),
    /** Machine-readable notices about the extraction (e.g. OCR_USED, SHEETS_READ). */
    noticesJson: text('notices_json', { mode: 'json' }).$type<string[]>().notNull(),
    countsJson: text('counts_json', { mode: 'json' }).$type<ImportCountsJson>().notNull(),
    /** Workbooks (S13b): the sheet names the teacher chose in the sheet picker; null = not a workbook / one sheet. */
    sheetsJson: text('sheets_json', { mode: 'json' }).$type<string[]>(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    committedAt: integer('committed_at'),
    committedBy: text('committed_by').references(() => users.id),
    revertedAt: integer('reverted_at'),
    revertedBy: text('reverted_by').references(() => users.id),
  },
  (t) => [index('import_batches_class_idx').on(t.targetClassId), index('import_batches_creator_idx').on(t.createdBy)],
);

/**
 * One extracted line/row of an import. `rawJson` = the cells as extracted (kept so the mapping can be
 * changed), `parsedJson` = the editable fields. Student ids are plain columns (no foreign keys), so a
 * revert can remove a student the batch created.
 */
export const importRows = sqliteTable(
  'import_rows',
  {
    id: text('id').primaryKey(),
    batchId: text('batch_id').notNull().references(() => importBatches.id),
    idx: integer('idx').notNull(),
    rawJson: text('raw_json', { mode: 'json' }).$type<string[]>().notNull(),
    page: integer('page'),
    parsedJson: text('parsed_json', { mode: 'json' }).$type<ImportParsedJson>().notNull(),
    /** The teacher edited the parsed fields by hand (a new mapping keeps them). */
    edited: integer('edited', { mode: 'boolean' }).notNull().default(false),
    ocrConfidence: integer('ocr_confidence'),
    flagsJson: text('flags_json', { mode: 'json' }).$type<ImportFlag[]>().notNull(),
    candidatesJson: text('candidates_json', { mode: 'json' }).$type<ImportCandidateJson[]>().notNull(),
    decision: text('decision', { enum: ['add', 'match', 'skip'] }).notNull(),
    /** 'auto' = suggested by the importer; 'teacher' = chosen in the preview (possible matches need it, IMP-4). */
    decisionSource: text('decision_source', { enum: ['auto', 'teacher'] }).notNull(),
    matchedStudentId: text('matched_student_id'),
    /** The teacher confirmed filling the matched student's missing number from this row (IMP-5). */
    fillNumber: integer('fill_number', { mode: 'boolean' }).notNull().default(false),
    filledNumber: integer('filled_number', { mode: 'boolean' }).notNull().default(false),
    createdStudentId: text('created_student_id'),
    createdEnrolmentId: text('created_enrolment_id'),
    outcome: text('outcome', { enum: ['added', 'matched', 'skipped', 'failed'] }),
    reason: text('reason'),
    revertOutcome: text('revert_outcome'),
  },
  (t) => [uniqueIndex('import_rows_batch_idx_uq').on(t.batchId, t.idx)],
);

// ---------------------------------------------------------------- goals, reflections, evidence (S10)
export const GOAL_STATUSES = ['active', 'achieved', 'archived'] as const;
export const GOAL_AUTHOR_TYPES = ['teacher', 'student'] as const;
export const GOAL_ENTRY_KINDS = ['progress', 'reflection', 'note', 'self_assessment'] as const;
export const EVIDENCE_KINDS = ['text', 'link', 'file', 'audio'] as const;
/** Label snapshot kept on a goal when it is created, so history stays readable after renames (DAT-6). */
export type GoalLabelSnapshot = { category: LocalizedText; preset?: LocalizedText };

/**
 * Skill categories (GOL-1). Seeded defaults have no subject and no creator (global: Reading, Writing,
 * Grammar, Vocabulary, Listening). Teachers add custom categories for one subject. Archived, never deleted.
 */
export const skillCategories = sqliteTable(
  'skill_categories',
  {
    id: text('id').primaryKey(),
    subjectId: text('subject_id').references(() => subjects.id),
    name: text('name', { mode: 'json' }).$type<LocalizedText>().notNull(),
    /** Simple icon key for lesson topics (S13a, `TOPIC_ICONS`); null = a generic book. */
    icon: text('icon'),
    sortOrder: integer('sort_order').notNull().default(0),
    createdBy: text('created_by').references(() => users.id),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('skill_categories_subject_idx').on(t.subjectId)],
);

/** Ready-made goals students (or teachers) can choose (GOL-1/2). Seeded defaults have no creator. */
export const goalPresets = sqliteTable(
  'goal_presets',
  {
    id: text('id').primaryKey(),
    categoryId: text('category_id').notNull().references(() => skillCategories.id),
    subjectId: text('subject_id').references(() => subjects.id),
    text: text('text', { mode: 'json' }).$type<LocalizedText>().notNull(),
    createdBy: text('created_by').references(() => users.id),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('goal_presets_category_idx').on(t.categoryId)],
);

/**
 * Sentence starters (S14d, D-152): short beginnings a student taps to start writing ("I want to get
 * better at ___."). `kind` says where they are offered (`STARTER_KINDS`); the blank is `___`.
 * Built-ins have fixed ids, no subject and no creator (seeded by `ensureStarterDefaults`); a teacher
 * adds starters for one subject (optionally one goal category). Archived, never deleted: a default by
 * an administrator for the school (`archivedAt`) or by a teacher for their own classes
 * (`default_item_archives`, kind 'starter').
 */
export const textStarters = sqliteTable(
  'text_starters',
  {
    id: text('id').primaryKey(),
    kind: text('kind', { enum: STARTER_KINDS }).notNull(),
    subjectId: text('subject_id').references(() => subjects.id),
    categoryId: text('category_id').references(() => skillCategories.id),
    text: text('text', { mode: 'json' }).$type<LocalizedText>().notNull(),
    sortOrder: integer('sort_order').notNull().default(0),
    createdBy: text('created_by').references(() => users.id),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('text_starters_subject_idx').on(t.subjectId, t.kind)],
);

/**
 * A student's goal in one subject (GOL-2). `authorType`/`authorId` say who wrote it (a teacher or the
 * student through the personal link); students may edit and delete only goals they wrote (GOL-5).
 * `labelSnapshot` keeps the category name as it was (DAT-6). Deleted = `deletedAt` (kept for audit).
 */
export const goals = sqliteTable(
  'goals',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    subjectId: text('subject_id').notNull().references(() => subjects.id),
    contextId: text('context_id').references(() => teachingContexts.id),
    categoryId: text('category_id').notNull().references(() => skillCategories.id),
    authorType: text('author_type', { enum: GOAL_AUTHOR_TYPES }).notNull(),
    authorId: text('author_id').notNull(),
    presetId: text('preset_id').references(() => goalPresets.id),
    text: text('text').notNull(),
    practiceChoicesJson: text('practice_choices_json', { mode: 'json' }).$type<string[]>().notNull(),
    reviewOn: text('review_on'),
    status: text('status', { enum: GOAL_STATUSES }).notNull().default('active'),
    labelSnapshot: text('label_snapshot', { mode: 'json' }).$type<GoalLabelSnapshot>().notNull(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    deletedAt: integer('deleted_at'),
    /** Hidden from the student page by a teacher (S13c moderation, D-123); the words are kept as written (GOL-5). */
    hiddenAt: integer('hidden_at'),
    hiddenBy: text('hidden_by'),
    /** When the goal became achieved (S13c review): the achievement rules date "goal reached" by this, not by `updatedAt`. */
    achievedAt: integer('achieved_at'),
  },
  (t) => [index('goals_student_subject_idx').on(t.studentId, t.subjectId)],
);

/**
 * Progress updates (teacher), reflections, notes and self-assessments (student) on a goal. A student
 * self-assessment (`confidence` 1–5) is stored here, separate from teacher assessments (GOL-3).
 */
export const goalEntries = sqliteTable(
  'goal_entries',
  {
    id: text('id').primaryKey(),
    goalId: text('goal_id').notNull().references(() => goals.id),
    authorType: text('author_type', { enum: GOAL_AUTHOR_TYPES }).notNull(),
    authorId: text('author_id').notNull(),
    kind: text('kind', { enum: GOAL_ENTRY_KINDS }).notNull(),
    body: text('body').notNull(),
    confidence: integer('confidence'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    deletedAt: integer('deleted_at'),
    hiddenAt: integer('hidden_at'),
    hiddenBy: text('hidden_by'),
  },
  (t) => [index('goal_entries_goal_idx').on(t.goalId)],
);

/** Teacher outcome for a goal (GOL-2/3). Students can read it but never write it (GOL-5). History kept. */
export const teacherAssessments = sqliteTable(
  'teacher_assessments',
  {
    id: text('id').primaryKey(),
    goalId: text('goal_id').notNull().references(() => goals.id),
    teacherId: text('teacher_id').notNull().references(() => users.id),
    outcome: text('outcome').notNull(),
    createdAt: integer('created_at').notNull(),
  },
  (t) => [index('teacher_assessments_goal_idx').on(t.goalId)],
);

/** Student-visible feedback from a teacher, on a goal or on the subject in general (GOL-6). */
export const teacherFeedback = sqliteTable(
  'teacher_feedback',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    subjectId: text('subject_id').notNull().references(() => subjects.id),
    goalId: text('goal_id').references(() => goals.id),
    teacherId: text('teacher_id').notNull().references(() => users.id),
    body: text('body').notNull(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    deletedAt: integer('deleted_at'),
  },
  (t) => [index('teacher_feedback_student_idx').on(t.studentId, t.subjectId)],
);

/**
 * Private teacher notes (GOL-6): readable only by the teacher who wrote them. There is no student read
 * path at all; no student endpoint queries this table (test-enforced).
 */
export const privateTeacherNotes = sqliteTable(
  'private_teacher_notes',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    subjectId: text('subject_id').notNull().references(() => subjects.id),
    teacherId: text('teacher_id').notNull().references(() => users.id),
    body: text('body').notNull(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    deletedAt: integer('deleted_at'),
  },
  (t) => [index('private_teacher_notes_student_idx').on(t.studentId, t.teacherId)],
);

/**
 * Evidence of learning (GOL-4): text, a web link (http/https only, never fetched), an uploaded file
 * (document or photo) or an audio recording, optionally on a goal. Files live in `files`
 * (owner = the student) and are served only through the policy-checked endpoints (STU-8).
 */
export const evidence = sqliteTable(
  'evidence',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    subjectId: text('subject_id').notNull().references(() => subjects.id),
    goalId: text('goal_id').references(() => goals.id),
    kind: text('kind', { enum: EVIDENCE_KINDS }).notNull(),
    body: text('body'),
    url: text('url'),
    fileId: text('file_id').references(() => files.id),
    authorType: text('author_type', { enum: GOAL_AUTHOR_TYPES }).notNull(),
    authorId: text('author_id').notNull(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    deletedAt: integer('deleted_at'),
    hiddenAt: integer('hidden_at'),
    hiddenBy: text('hidden_by'),
  },
  (t) => [index('evidence_student_subject_idx').on(t.studentId, t.subjectId), index('evidence_file_idx').on(t.fileId)],
);

// ---------------------------------------------------------------- personal student links (S10, S13b2)
export const STUDENT_LINK_ORIGINS = ['auto', 'teacher', 'emergency'] as const;
export const STUDENT_LINK_REVOKE_KINDS = ['replaced', 'teacher', 'emergency_revoke', 'emergency_replace', 'legacy'] as const;
/**
 * Personal links (STU-1..6). An HMAC of the 256-bit token is the lookup key (`tokenHash`, server
 * pepper). Since S13b2 (D-115) links are permanent and made automatically for every active student
 * (`origin` 'auto', no creator); the token is also stored ENCRYPTED (`tokenCipher`, AES-256-GCM with
 * a key derived from the pepper by HKDF, bound to the row id) so the same card can be printed again.
 * At most one active (not revoked) link per student. Revoking is an emergency action only
 * (`revokeKind`, with the typed reason); student sessions point at the link and every request
 * re-checks it (STU-3).
 */
export const studentLinks = sqliteTable(
  'student_links',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    tokenHash: text('token_hash').notNull(),
    /** `v1.<base64url(iv | ciphertext | tag)>`; null for links made before S13b2 (revoked by the migration). */
    tokenCipher: text('token_cipher'),
    generation: integer('generation').notNull(),
    origin: text('origin', { enum: STUDENT_LINK_ORIGINS }).notNull().default('teacher'),
    /** null = made automatically. */
    createdBy: text('created_by').references(() => users.id),
    createdAt: integer('created_at').notNull(),
    revokedAt: integer('revoked_at'),
    revokedBy: text('revoked_by').references(() => users.id),
    revokeKind: text('revoke_kind', { enum: STUDENT_LINK_REVOKE_KINDS }),
    /** The reason typed for an emergency revoke or replacement. */
    revokeReason: text('revoke_reason'),
    lastUsedAt: integer('last_used_at'),
  },
  (t) => [
    uniqueIndex('student_links_token_uq').on(t.tokenHash),
    uniqueIndex('student_links_active_uq').on(t.studentId).where(sql`revoked_at IS NULL`),
  ],
);

export const DEFAULT_ITEM_KINDS = ['preset', 'category', 'achievement', 'starter'] as const;
/**
 * Default goal presets, skill categories, (S13c) achievements and (S14d) sentence starters a teacher archived for their own classes (S13b2, D-116).
 * A default archived school-wide by an administrator uses the row's own `archivedAt` instead.
 */
export const defaultItemArchives = sqliteTable(
  'default_item_archives',
  {
    userId: text('user_id').notNull().references(() => users.id),
    kind: text('kind', { enum: DEFAULT_ITEM_KINDS }).notNull(),
    itemId: text('item_id').notNull(),
    archivedAt: integer('archived_at').notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.kind, t.itemId] })],
);

// ---------------------------------------------------------------- achievements (S13c)
export const ACHIEVEMENT_TIER_VALUES = ['bronze', 'silver', 'gold', 'none'] as const;
export const ACHIEVEMENT_CATEGORY_VALUES = ['goals', 'evidence', 'reflections', 'homework', 'skills', 'roles', 'secret', 'speakers', 'teacher', 'custom'] as const;
export const AWARD_SOURCES = ['auto', 'manual', 'backfill'] as const;

/**
 * Achievement definitions (D-121). Defaults have a `key` and no creator (seeded once with fixed ids;
 * archivable school-wide with `archivedAt` or per teacher in `default_item_archives`). Teachers'
 * own badges have `createdBy` and the subject they were made for. `ruleJson` (auto badges only) is
 * `{ event, threshold, skill?, evidenceKind? }` from the shared rule menu.
 */
export const achievementDefinitions = sqliteTable(
  'achievement_definitions',
  {
    id: text('id').primaryKey(),
    key: text('key'),
    name: text('name', { mode: 'json' }).$type<LocalizedText>().notNull(),
    description: text('description', { mode: 'json' }).$type<LocalizedText>().notNull(),
    icon: text('icon').notNull(),
    tier: text('tier', { enum: ACHIEVEMENT_TIER_VALUES }).notNull(),
    category: text('category', { enum: ACHIEVEMENT_CATEGORY_VALUES }).notNull(),
    kind: text('kind', { enum: ['auto', 'manual'] }).notNull(),
    ruleJson: text('rule_json', { mode: 'json' }).$type<{ event: string; threshold: number; skill?: string; evidenceKind?: string }>(),
    subjectId: text('subject_id').references(() => subjects.id),
    createdBy: text('created_by').references(() => users.id),
    archivedAt: integer('archived_at'),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [uniqueIndex('achievement_definitions_key_uq').on(t.key), index('achievement_definitions_creator_idx').on(t.createdBy)],
);

/**
 * Awards (D-121). One live award per student, achievement and class+subject (partial unique index;
 * replays never double-award). `nameSnapshot`/`iconSnapshot`/`tierSnapshot` keep the badge as it was
 * (DAT-6). `awardedBy` null = automatic. A mistaken manual award is revoked (who, when, why), never
 * deleted. `quiet` = given by "award past achievements quietly" (no celebration). `seenAt` = the
 * student has seen it on their page (the celebration plays once).
 */
export const studentAchievements = sqliteTable(
  'student_achievements',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    achievementId: text('achievement_id').notNull().references(() => achievementDefinitions.id),
    contextId: text('context_id').references(() => teachingContexts.id),
    lessonId: text('lesson_id'),
    awardedAt: integer('awarded_at').notNull(),
    awardedBy: text('awarded_by').references(() => users.id),
    source: text('source', { enum: AWARD_SOURCES }).notNull(),
    /** What caused it, e.g. the command opId or `event:<kind>`. Never free text. */
    sourceRef: text('source_ref'),
    nameSnapshot: text('name_snapshot', { mode: 'json' }).$type<LocalizedText>().notNull(),
    iconSnapshot: text('icon_snapshot').notNull(),
    tierSnapshot: text('tier_snapshot', { enum: ACHIEVEMENT_TIER_VALUES }).notNull(),
    quiet: integer('quiet', { mode: 'boolean' }).notNull().default(false),
    seenAt: integer('seen_at'),
    revokedAt: integer('revoked_at'),
    revokedBy: text('revoked_by').references(() => users.id),
    revokeReason: text('revoke_reason'),
  },
  (t) => [
    uniqueIndex('student_achievements_live_uq').on(t.studentId, t.achievementId, t.contextId).where(sql`revoked_at IS NULL`),
    index('student_achievements_student_idx').on(t.studentId),
    index('student_achievements_context_idx').on(t.contextId, t.awardedAt),
  ],
);

// ---------------------------------------------------------------- student text checks (S13c)
/**
 * Extra words for the language check (D-123): the school's block and allow lists (`ownerId` '') and
 * words a teacher added for their classes (`ownerId` = the teacher). Lower-case, NFC.
 */
export const textCheckWords = sqliteTable(
  'text_check_words',
  {
    id: text('id').primaryKey(),
    scope: text('scope', { enum: ['school', 'teacher'] }).notNull(),
    ownerId: text('owner_id').notNull().default(''),
    list: text('list', { enum: ['block', 'allow'] }).notNull(),
    word: text('word').notNull(),
    createdAt: integer('created_at').notNull(),
    createdBy: text('created_by').references(() => users.id),
  },
  (t) => [uniqueIndex('text_check_words_uq').on(t.scope, t.ownerId, t.list, t.word)],
);

/**
 * How often a student tried to save text with a blocked word, per subject and local day (D-123).
 * Counts only: the text itself is never stored.
 */
export const textCheckAttempts = sqliteTable(
  'text_check_attempts',
  {
    studentId: text('student_id').notNull().references(() => students.id),
    subjectId: text('subject_id').notNull().references(() => subjects.id),
    localDate: text('local_date').notNull(),
    count: integer('count').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [primaryKey({ columns: [t.studentId, t.subjectId, t.localDate] })],
);

// ---------------------------------------------------------------- operations (S11)
export const BACKUP_RUN_KINDS = ['local', 'pre_migration', 'verify', 'offsite', 'offsite_check', 'restore'] as const;
export const BACKUP_RUN_TRIGGERS = ['cli', 'admin', 'startup', 'timer'] as const;

/**
 * Every backup, verification, off-site copy, repository check and restore (DAT-4, D-089). Written by
 * the CLI and the admin "back up now" button; read by the admin Maintenance page. `detailsJson`
 * holds counts, checksums summary or a sanitised error message (never credentials or repository
 * passwords). A restore is recorded in the restored database after the swap.
 */
export const backupRuns = sqliteTable(
  'backup_runs',
  {
    id: text('id').primaryKey(),
    kind: text('kind', { enum: BACKUP_RUN_KINDS }).notNull(),
    trigger: text('trigger', { enum: BACKUP_RUN_TRIGGERS }).notNull(),
    status: text('status', { enum: ['ok', 'failed'] }).notNull(),
    startedAt: integer('started_at').notNull(),
    finishedAt: integer('finished_at').notNull(),
    /** Backup file name (no directory). */
    fileName: text('file_name'),
    sizeBytes: integer('size_bytes'),
    appVersion: text('app_version').notNull(),
    migrationLevel: text('migration_level').notNull(),
    detailsJson: text('details_json', { mode: 'json' }).$type<Record<string, unknown>>(),
    actorId: text('actor_id'),
  },
  (t) => [index('backup_runs_kind_idx').on(t.kind, t.finishedAt)],
);

export const _sqlHelper = sql; // re-export for raw fragments in repos

// ---------------------------------------------------------------- Super Speakers (S12)
/**
 * Scorer links (S12, D-128): an administrator gives a teacher a special link to award Super Speakers
 * points, whether or not that teacher uses Class Compass otherwise. `tokenHash` = HMAC(pepper, token)
 * is the lookup key; the token is also kept encrypted (`tokenCipher`, like student links, D-115) so
 * the administrator can copy and show the QR code again. Regenerating gives the same row a new token
 * (`generation` + 1) and ends every session of the old one; revoking ends them too. Awards keep
 * pointing at the row, so history survives both. `locale` is the scorer app's starting language.
 */
export const scorerLinks = sqliteTable(
  'scorer_links',
  {
    id: text('id').primaryKey(),
    label: text('label').notNull(),
    locale: text('locale', { enum: ['en', 'tr'] }).notNull().default('en'),
    /** Optional teacher account this link belongs to (recorded on every award). */
    userId: text('user_id').references(() => users.id),
    tokenHash: text('token_hash').notNull(),
    tokenCipher: text('token_cipher'),
    generation: integer('generation').notNull().default(1),
    createdBy: text('created_by').references(() => users.id),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    revokedAt: integer('revoked_at'),
    revokedBy: text('revoked_by').references(() => users.id),
    lastUsedAt: integer('last_used_at'),
  },
  (t) => [uniqueIndex('scorer_links_token_uq').on(t.tokenHash)],
);

/**
 * One-time 6-digit pairing codes (S12, D-129): the installed scorer app on an iPhone has its own
 * cookie store, so the link page shows a code that the installed app exchanges for its own session.
 * Only HMAC(pepper, code) is stored; a code works once, for 10 minutes.
 */
export const scorerPairings = sqliteTable(
  'scorer_pairings',
  {
    id: text('id').primaryKey(),
    scorerLinkId: text('scorer_link_id').notNull().references(() => scorerLinks.id),
    codeHash: text('code_hash').notNull(),
    createdAt: integer('created_at').notNull(),
    expiresAt: integer('expires_at').notNull(),
    usedAt: integer('used_at'),
  },
  (t) => [index('scorer_pairings_code_idx').on(t.codeHash), index('scorer_pairings_link_idx').on(t.scorerLinkId)],
);

/** Read-only board links (S12, D-128): same token pattern as scorer links, revocable and regenerable. */
export const displayLinks = sqliteTable(
  'display_links',
  {
    id: text('id').primaryKey(),
    label: text('label').notNull(),
    tokenHash: text('token_hash').notNull(),
    tokenCipher: text('token_cipher'),
    generation: integer('generation').notNull().default(1),
    createdBy: text('created_by').references(() => users.id),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    revokedAt: integer('revoked_at'),
    revokedBy: text('revoked_by').references(() => users.id),
    lastUsedAt: integer('last_used_at'),
  },
  (t) => [uniqueIndex('display_links_token_uq').on(t.tokenHash)],
);

/**
 * Super Speakers points (S12, D-130): one row per +1 (positive points only), `id` = the command opId.
 * `localDate` and `weekStart` are computed in the school timezone when the point is written; the
 * class is a snapshot (id + name) so a later class change keeps the history as it was (DAT-6). A
 * mistaken point is voided (by its scorer within the undo window, or by an administrator with a
 * reason), never deleted. The weekly reset is only a time window: nothing is ever removed.
 */
export const pointEvents = sqliteTable(
  'point_events',
  {
    id: text('id').primaryKey(),
    studentId: text('student_id').notNull().references(() => students.id),
    scorerLinkId: text('scorer_link_id').notNull().references(() => scorerLinks.id),
    /** The teacher account linked to the scorer link when the point was given (null = none). */
    userId: text('user_id').references(() => users.id),
    occurredAt: integer('occurred_at').notNull(),
    localDate: text('local_date').notNull(),
    weekStart: text('week_start').notNull(),
    classIdSnapshot: text('class_id_snapshot').notNull().references(() => classes.id),
    classNameSnapshot: text('class_name_snapshot').notNull(),
    voidedAt: integer('voided_at'),
    /** 'scorer:<linkId>' (own undo) or the administrator's user id. */
    voidedBy: text('voided_by'),
    voidReason: text('void_reason'),
  },
  (t) => [
    index('point_events_date_idx').on(t.localDate),
    index('point_events_student_idx').on(t.studentId, t.occurredAt),
    index('point_events_scorer_idx').on(t.scorerLinkId, t.occurredAt),
  ],
);

/**
 * School-wide Super Speakers settings (S12, D-131), one row (id 1). `participatingClassIds` null =
 * every active class of the current school year. `boardTitle` is `{en,tr}`; `theme` is a key of the
 * theme registry. `badgeSubjectId` = the subject whose class+subjects receive the Super Speakers
 * badges (null = found by its English name "English", D-132).
 */
export const superSpeakersSettings = sqliteTable('super_speakers_settings', {
  id: integer('id').primaryKey(),
  weekStartsOn: integer('week_starts_on').notNull().default(1),
  participatingClassIds: text('participating_class_ids', { mode: 'json' }).$type<string[]>(),
  undoWindowMinutes: integer('undo_window_minutes').notNull().default(10),
  rateLimitMax: integer('rate_limit_max').notNull().default(60),
  rateLimitWindowMinutes: integer('rate_limit_window_minutes').notNull().default(10),
  boardTitle: text('board_title', { mode: 'json' }).$type<LocalizedText>().notNull(),
  /** Board messages {en,tr} (S12 review); null or an empty text = the built-in translated message. */
  boardMessages: text('board_messages', { mode: 'json' }).$type<{ placeholder: LocalizedText; waiting: LocalizedText }>(),
  boardLanguage: text('board_language', { enum: ['en', 'tr'] }).notNull().default('en'),
  theme: text('theme').notNull().default('explorer'),
  boardSound: integer('board_sound', { mode: 'boolean' }).notNull().default(false),
  badgeSubjectId: text('badge_subject_id').references(() => subjects.id),
  updatedAt: integer('updated_at').notNull(),
  updatedBy: text('updated_by'),
});

// ---------------------------------------------------------------- report views & user settings (S14e1, D-153)
/**
 * Saved report views ("templates", S14e1, D-153): a name and the sections/tables to show
 * (`ReportViewSpec`, shared/reportViews.ts). Personal to the account and to where it was saved
 * (`viewer`: teacher area or admin area); never a class, a student or a period, so no student data.
 * At most MAX_REPORT_VIEWS per account; deleted for good (a personal preference, not history).
 */
export const reportViews = sqliteTable(
  'report_views',
  {
    id: text('id').primaryKey(),
    userId: text('user_id').notNull().references(() => users.id),
    viewer: text('viewer', { enum: ['teacher', 'admin'] }).notNull(),
    name: text('name').notNull(),
    specJson: text('spec_json', { mode: 'json' }).$type<{ sections: Array<{ key: string; tables: string[] | null }> }>().notNull(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [index('report_views_user_idx').on(t.userId, t.viewer)],
);

/**
 * Small per-account settings that follow the user across devices (S14e1, D-153), one row per
 * (account, key). Keys and their value schemas are registered in `server/lib/userSettings.ts` (the
 * only reader and writer): the default report view now, the notification settings later (S14e3).
 */
export const userSettings = sqliteTable(
  'user_settings',
  {
    userId: text('user_id').notNull().references(() => users.id),
    key: text('key').notNull(),
    valueJson: text('value_json', { mode: 'json' }).$type<unknown>().notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.key] })],
);

// ---------------------------------------------------------------- theme packages (S14g, D-158)
/**
 * Imported theme packages. `packageJson` is the package exactly as validated (`shared/themePackage`),
 * `reportJson` its validation report at import time (warnings only: a package with errors is never
 * stored). `status`: a draft can be previewed but not chosen; enabled themes are offered next to the
 * built-in ones; a disabled theme keeps its classes' choice but they show the default theme. Deleting
 * removes the row and moves its classes and the Super Speakers board to the default (audited).
 */
export const customThemes = sqliteTable('custom_themes', {
  key: text('key').primaryKey(),
  packageJson: text('package_json', { mode: 'json' }).$type<Record<string, unknown>>().notNull(),
  reportJson: text('report_json', { mode: 'json' }).$type<Record<string, unknown>>().notNull(),
  status: text('status', { enum: ['draft', 'enabled', 'disabled'] }).notNull().default('draft'),
  bytes: integer('bytes').notNull(),
  createdBy: text('created_by').references(() => users.id),
  updatedBy: text('updated_by').references(() => users.id),
  createdAt: integer('created_at').notNull(),
  updatedAt: integer('updated_at').notNull(),
});

// ---------------------------------------------------------------- classroom board layout (S14b)
/**
 * A teacher's own classroom board layout (S14b, D-148): `scope` is 'all' (every class of the
 * teacher) or a teaching context id (one class+subject; it wins over 'all'). `layoutJson` is a
 * `ClassroomLayout` (shared/classroomLayout.ts), validated on every write and again on every read (an
 * invalid stored layout is never served: the board falls back to the default). A personal display
 * preference: no student data, not audited, replaced in place (`version` feeds the ETag).
 */
export const classroomLayouts = sqliteTable(
  'classroom_layouts',
  {
    userId: text('user_id').notNull().references(() => users.id),
    scope: text('scope').notNull(),
    layoutJson: text('layout_json', { mode: 'json' }).$type<unknown>().notNull(),
    version: integer('version').notNull(),
    updatedAt: integer('updated_at').notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.scope] })],
);

// ---------------------------------------------------------------- teacher notifications (S14e3, D-155)
/**
 * What students did that a teacher may want to see (the bell, `/teacher/notifications`). One row per
 * recipient teacher, with ids only: the text shown is read at display time after the access check, so
 * hidden or deleted items and students the teacher no longer teaches never show. `subjectId` null =
 * about the student as a whole (avatar, link). `contextId` is the recipient's own class+subject for
 * the student (deep links). The daily aggregate categories (`AGGREGATE_CATEGORIES`: blocked text,
 * Super Speakers points) keep one row per teacher, student, category and local day with a `count`
 * (unique partial index); other categories bump the count of an unread row about the same record.
 * `digestedCount` keeps the daily digest to what is new since the last one (S14e3 review).
 * Purged after NOTIFICATION_RETENTION_DAYS (90) by the notifications tick; erased with the student
 * (`student_id`); in the full export, not in the per-student export (teacher-side data, like notes).
 */
export const notifications = sqliteTable(
  'notifications',
  {
    id: text('id').primaryKey(),
    userId: text('user_id').notNull().references(() => users.id),
    studentId: text('student_id').notNull().references(() => students.id),
    subjectId: text('subject_id').references(() => subjects.id),
    contextId: text('context_id').references(() => teachingContexts.id),
    category: text('category', { enum: NOTIFICATION_CATEGORIES }).notNull(),
    entity: text('entity', { enum: NOTIFICATION_ENTITIES }).notNull(),
    entityId: text('entity_id'),
    count: integer('count').notNull().default(1),
    /**
     * How much of `count` the teacher already had: counted in a digest that went out, or there when the
     * teacher read the row before it became unread again. The digest mails only `count - digestedCount`.
     */
    digestedCount: integer('digested_count').notNull().default(0),
    /** The day it happened (school timezone), for the daily aggregates and the digest. */
    localDate: text('local_date').notNull(),
    createdAt: integer('created_at').notNull(),
    updatedAt: integer('updated_at').notNull(),
    readAt: integer('read_at'),
  },
  (t) => [
    index('notifications_user_idx').on(t.userId, t.updatedAt),
    index('notifications_entity_idx').on(t.userId, t.category, t.entityId),
    index('notifications_student_idx').on(t.studentId),
    index('notifications_created_idx').on(t.createdAt),
    uniqueIndex('notifications_daily_uq')
      .on(t.userId, t.studentId, t.category, t.localDate)
      .where(sql`category in ('textBlocked', 'speakersPoints')`),
  ],
);

/**
 * The daily email digest (S14e3, D-155): one row per teacher and local day once the day's digest was
 * decided, so a teacher gets at most one email a day. `itemsJson` holds counts per category only
 * (never names or student text). `status`: `sending` while the mail is out, then `sent`, `failed`
 * (not retried that day) or `empty` (nothing new, no email).
 */
export const notificationDigests = sqliteTable(
  'notification_digests',
  {
    userId: text('user_id').notNull().references(() => users.id),
    localDate: text('local_date').notNull(),
    sentAt: integer('sent_at').notNull(),
    status: text('status', { enum: ['sending', 'sent', 'failed', 'empty'] }).notNull(),
    itemsJson: text('items_json', { mode: 'json' }).$type<Record<string, number>>().notNull(),
  },
  (t) => [primaryKey({ columns: [t.userId, t.localDate] })],
);
